/**
 * Project-level software release containing version identifiers, release notes, and incremental gray state.
 */
export type Version = {
    /**
     * Live gray actual coverage (allowlisted/N*100) while gray is in progress; 100 after full push. Omitted on drafts that never started gray.
     */
    actual_percent?: number;
    auto_publish_when?: AutoPublishRule;
    changelog?: ChangelogMap;
    /**
     * Target distribution channel slug (e.g. 'stable', 'beta').
     */
    channel?: string;
    /**
     * Creation timestamp (UTC ISO-8601).
     */
    created_at?: string;
    /**
     * Git commit SHA associated with this build.
     */
    git_commit?: string | null;
    /**
     * Starting git commit SHA for automatically generated changelog.
     */
    git_log_from?: string | null;
    /**
     * Ending git commit SHA for automatically generated changelog.
     */
    git_log_to?: string | null;
    /**
     * Git tag associated with this build.
     */
    git_tag?: string | null;
    /**
     * When gray completed (full push). Null means allowlist-only.
     */
    gray_completed_at?: string | null;
    /**
     * Seconds between coverage ticks. k = floor(elapsed / interval).
     */
    gray_interval_seconds?: number;
    /**
     * Starting gray coverage percent at t=0. 100 (default) publishes as full push.
     */
    gray_start_percent?: number;
    /**
     * When incremental gray started (publish time).
     */
    gray_started_at?: string | null;
    /**
     * Coverage percent added after each interval tick.
     */
    gray_step_percent?: number;
    /**
     * Unique version identifier (UUID v4).
     */
    id?: string;
    /**
     * True if this release contains urgent security fixes; forces immediate update and ignores gray rollout.
     */
    is_critical?: boolean;
    /**
     * True if this version is marked as a Long-Term Support release.
     */
    is_lts?: boolean;
    /**
     * Platform slices included on GET version detail.
     */
    lines?: Array<VersionLine>;
    /**
     * Oldest source version permitted to upgrade directly to this version without passing through an intermediate.
     */
    min_source_version?: string | null;
    /**
     * ID of the owning project.
     */
    project_id?: string;
    /**
     * UTC timestamp when the version was published.
     */
    publish_time?: string;
    /**
     * Lifecycle state: 'draft', 'published', 'deprecated', 'revoked'.
     */
    status?: 'draft' | 'published' | 'deprecated' | 'revoked';
    /**
     * Last modification timestamp (UTC ISO-8601).
     */
    updated_at?: string;
    /**
     * Integer build number (must be unique within the project).
     */
    version_integer?: number | null;
    /**
     * Semantic version string compliant with SemVer 2.0 (unique ignoring build metadata).
     */
    version_semver?: string | null;
};

