export type CreateProjectData = {
    /**
     * Project configuration parameters for creation.
     */
    body: {
        changelog_client_override?: boolean;
        changelog_include_platform_notes?: boolean;
        changelog_include_revoked?: boolean;
        changelog_layout?: string;
        changelog_scope?: string;
        compare_engine?: 'semver' | 'integer';
        cors_origins?: Array<string>;
        /**
         * Required. Seeds the project's single default language row. Do not omit.
         */
        default_locale: string;
        device_id_policy?: 'hashed' | 'raw' | 'none';
        store_token?: string;
        force_https?: boolean;
        /**
         * When true (default), auto gray admission ranks by tenure×recency. When false, created_at,id ASC.
         */
        gray_weight_tenure_activity?: boolean;
        minimum_supported_version?: string | null;
        name?: string;
        owner_password?: string;
        /**
         * Optional project owner. With owner_password creates a non-platform account; without it attaches an existing account.
         */
        owner_username?: string;
        rate_limit?: {
            [key: string]: unknown;
        };
        require_client_token?: boolean;
        /**
         * TTL in seconds for short-lived signed download URLs of private-storage projects. 0 means the instance default (3600).
         */
        signed_url_ttl_seconds?: number;
        signing_algo?: 'ed25519' | 'rsa-sha256';
        signing_private_key?: string;
        signing_public_key?: string;
        slug: string;
        slug_alias_retention_days?: number;
        /**
         * Days to retain telemetry events. Default 90. Negative values are rejected; 0 is treated as 90.
         */
        telemetry_retention_days?: number;
        cache_s_maxage_seconds?: number;
        /**
         * Per-project file_list pending-file cap. 0 inherits the platform ceiling.
         */
        file_list_max_files?: number;
        storage_bucket?: string;
        storage_prefix?: string;
        /**
         * Must be public. private is 400 INVALID_REQUEST.
         */
        storage_visibility?: 'public' | 'private';
        /**
         * Optional display names for the three system channels. Omitted fields fall back to English slugs.
         */
        system_channel_names?: {
            alpha?: string;
            beta?: string;
            stable?: string;
        };
        webhook_secret_reset?: boolean;
        webhook_url?: string;
        /**
         * Changelog entries when from_version is omitted. Must not exceed changelog_default_entries_limit or the effective max.
         */
        changelog_default_entries?: number;
        /**
         * Changelog truncation cap. 0 inherits the instance max_entries.
         */
        changelog_max_entries?: number;
    };
    path?: never;
    query?: never;
    url: '/api/v1/admin/projects';
};

