export type PatchTusUploadData = {
    /**
     * Binary chunk stream.
     */
    body: Blob | File;
    headers: {
        /**
         * Current byte offset at which the chunk begins.
         */
        'Upload-Offset': number;
        /**
         * MIME media type header for the request body.
         */
        'Content-Type': string;
        /**
         * TUS protocol specification version (1.0.0).
         */
        'Tus-Resumable': string;
    };
    path: {
        /**
         * Project UUID, active slug, or retained slug alias.
         */
        project_ref: string;
        /**
         * TUS 1.0 upload session UUID.
         */
        upload_id: string;
    };
    query?: never;
    url: '/api/v1/admin/projects/{project_ref}/artifacts/tus/{upload_id}';
};

export type PatchTusUploadErrors = {
    /**
     * CHECKSUM_MISMATCH
     */
    400: _Error;
    /**
     * OFFSET_MISMATCH / ARTIFACT_IMMUTABLE
     */
    409: _Error;
};

export type PatchTusUploadError = PatchTusUploadErrors[keyof PatchTusUploadErrors];

export type PatchTusUploadResponses = {
    /**
     * Chunk written successfully; returns updated Upload-Offset header.
     */
    204: void;
};

